corrected_code:
const express = require('express');
const { Coupon } = require('../models/coupon');

const app = express();
app.use(express.json());

const storeRouter = express.Router({ mergeParams: true });

app.use('/stores/:storeId/merchandise', (req, res, next) => {
  if (!req.session || !req.session.merchantId) {
    return res.status(401).json({ error: 'Merchant authentication required' });
  }

  // Validate merchant manages store
  if (req.session.managedStoreId !== req.params.storeId) {
    return res.status(403).json({ error: 'Forbidden: you do not manage this store' });
  }
  next();
}, storeRouter);

storeRouter.patch('/:storeId/coupons/:couponId', async (req, res) => {
  const { discountPercentage, active } = req.body;

  // Scope query strictly to both couponId and storeId
  const coupon = await Coupon.findOneAndUpdate(
    { _id: req.params.couponId, storeId: req.params.storeId },
    { discountPercentage, active },
    { new: true }
  );

  if (!coupon) {
    return res.status(404).json({ error: 'Coupon not found in this store' });
  }

  res.json({ coupon });
});

app.listen(9000);
